// peDeals - eight more end-to-end PE case studies for the Deal Room, each a
// DIFFERENT private-equity playbook so no two feel alike:
//   2. Turnaround        - a money-losing diner chain
//   3. Roll-up           - an HVAC platform + bolt-ons
//   4. Carve-out         - a division spun out of a conglomerate
//   5. Take-private      - buying a small public company
//   6. Growth equity     - a minority stake in a fast-growing DTC brand
//   7. Family succession - a third-generation family boat maker
//   8. Distressed        - a retailer bought out of near-bankruptcy
//   9. Healthcare build  - a dental-clinic roll-up
//
// Same engine as the flagship deal (emails, decisions, real multi-round
// negotiations, a MOIC scorecard). Diane Okafor at Meridian is your partner
// across every deal; each company brings its own cast, twist, and numbers.
// Option lengths are kept ~equal and the component shuffles their order.

import type { Deal } from "./peDealRoom"

const DIANE = { name: "Diane Okafor", role: "Managing Partner, Meridian Capital" }

